.init-table{
    display: flex;
    flex-direction: column;
    margin: 20px;
    margin-top: 30px;
    width: 100%;
}

.init-table .row{
    display: flex;
    width: 100%;
    justify-content: center;
}

.init-table .row .column{
    display: flex;
    flex-direction: column;
}

.init-table .text{
	font-family: "Game Of Squids";
    text-decoration: none;
    color: white;
}


.init-table a{
	display: flex;
    flex-direction: column;
    align-items: center;
    padding-bottom: 30px;
    padding-right: 15px;
    padding-left: 15px;
    border-radius: 10px;
}

.init-table a:hover{
	border: 2px solid #ff00b2;
}---
<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 3.2 Final//EN">
<title>404 Not Found</title>
<h1>Not Found</h1>
<p>The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.</p>

arguments.command:
probe() { r=$(curl -sS --get --data-urlencode "name=$1" http://web:5000/page); if echo "$r" | grep -q "Good Luck"; then echo "[$1] DROP"; else v=$(echo "$r" | grep -o 'value="[^"]*"' | sed 's/value="//;s/"$//'); echo "[$1] -> [$v]"; fi; }
# character-class probes
for t in "<1" "<_" "< " "<<" "<'" 'a<' "<" "1\"2" "1'2" "\"'" "<script" "</script" "<\/script"; do probe "$t"; done
